import { MiUserIp } from 'backend-upstream/entities';
import { apiIpLogging } from '../http/api-ip-log.js';
import { createApiIpLog } from '../platform/api-ip-log.js';
import { createNoteChartsApi, createUsersChartsApi } from '../http/note-charts-api.js';
import { createTokenAuthenticator } from '../platform/database/authenticate.js';
import { getAvatarImagesPath } from '../http/avatar-images-api.js';

const ipLog = createApiIpLog({
	enabled: async () => (await resources.meta.fetch()).enableIpLogging,
	insert: row => resources.dataSource.getRepository(MiUserIp).createQueryBuilder().insert().values(row).orIgnore(true).execute(),
	now: () => new Date(),
	onError: error => resources.logger.error('api.ip-log-failed', { error }),
});

trustProxy: optional(source.trustProxy, value => {
	if (typeof value === 'boolean' || typeof value === 'number') {
		return value;
	}
	return Array.isArray(value) ? texts(value, 'trustProxy') : text(value, 'trustProxy');
}),

const userIp = source.getMetadata('MiUserIp');
expect(userIp.tableName).toBe('user_ip');
expect(userIp.indices.some(index => index.isUnique && index.columns.map(column => column.propertyName).join(',') === 'userId,ip')).toBe(true);
expect(source.entityMetadatas).toHaveLength(45);

test.each([false, true, 1, 'loopback', ['127.0.0.1/32', '10.0.0.0/8']])('preserves configured trustProxy: %j', async trustProxy => {
	const value = await loadConfig({ configFile: await configFrom({ url: 'https://example.test', port: 3000, db: { host: 'localhost', port: 5432, db: 'test', user: 'test' }, redis: { host: 'localhost', port: 6379 }, trustProxy }) });
	expect(value.trustProxy).toEqual(trustProxy);
});
